std__collections__List_str std__collections__List_str_init(kobel_str* items_data, size_t items_len) {
size_t cap = items_len < 4 ? 4 : items_len;
kobel_str* buf = std__memory__Heap_create_str(cap);
{
size_t __for_e = items_len;
size_t __for_i = __for_e;
__for_i = 0;
bool __for_up = __for_i <= __for_e;
bool __for_go = false;
if (__for_up) {
__for_go = __for_i < __for_e;
} else {
__for_go = __for_i > __for_e;
}
while (__for_go) {
size_t i = __for_i;
buf[i] = items_data[i];
if (__for_up) {
__for_go = __for_i + 1 < __for_e;
} else {
__for_go = __for_i - 1 > __for_e;
}
if (__for_go) {
if (__for_up) {
__for_i = __for_i + 1;
} else {
__for_i = __for_i - 1;
}
}
}
}
return (std__collections__List_str){ buf, items_len, cap };
}

